// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 playCount) public {
        playCount = bound(playCount, 1, 5);
        address player = address(0x1234);
        vm.deal(player, 100 ether);
        vm.startPrank(player);
        for (uint256 i = 0; i < playCount; i++) {
            c.play{value: 10}();
        }
        vm.stopPrank();
        assertEq(address(c).balance, c.pot(), "invariant: balance == pot");
    }
}
